[
  {
    "statement": "Deploying fishing nets at different depths is effective at reducing marine mammal entanglements.",
    "citations": [
      "2793"
    ]
  },
  {
    "statement": "Fishing nets deployed 4.5 m below the water surface in the Arafura Sea had fewer entanglements of dolphins than surface nets.",
    "citations": [
      "2793"
    ]
  },
  {
    "statement": "Using acoustically reflective fishing gear materials can reduce entanglements.",
