[
  {
    "statement": "Legally protecting marine mammal species and their habitats shows several population-level effects.",
    "citations": []
  },
  {
    "statement": "Studies on habitat protection for marine mammals found mixed but generally positive effects.",
    "citations": []
  },
  {
    "statement": "Mediterranean monk seal populations increased after eight years of island protection.",
    "citations": []
  },
  {
    "statement": "Bottlenose dolphin populations maintained similar sizes before and after habitat protection.",
    "citations": []
  },
  {
    "statement": "Hector's dolphins showed higher survival rates after coastal area protection.",
    "citations": []
  },
  {
    "statement": "Human-caused strandings decreased after area protection.",
    "citations": []
  },
  {
    "statement": "Overall strandings remained similar after area protection.",
    "citations": []
  },
  {
    "statement": "Four out of five studies found that the abundance of marine mammals increased after hunting bans.",
    "citations": []
  },
  {
    "statement": "The populations of harbour seals and humpback whales increased over a period of 7 to 30 years after hunting bans.",
    "citations": []
  },
  {
    "statement": "Ten of twelve baleen whale populations showed significant increases during the 7 to 21 years after protective legislation was enacted.",
    "citations": []
  },
  {
    "statement": "No studies were found that evaluated the direct effects of legally protecting marine mammal species themselves.",
    "citations": []
  },
  {
    "statement": "One study found no significant change in the number of mature male sperm whales 31 years after a hunting prohibition.",
    "citations": []
  }
]

[
  {
    "statement": "The evidence base for interventions to reduce lethal vessel collisions with marine mammals is extremely limited.",
    "citations": []
  },
  {
    "statement": "Setting and enforcing vessel speed limits is the only intervention type that has been evaluated in any studies.",
    "citations": []
  },
  {
    "statement": "Two before-and-after studies have examined the intervention of setting and enforcing vessel speed limits.",
    "citations": []
  },
  {
    "statement": "One study on vessel speed limits was conducted in the Indian River estuarine system in the USA.",
    "citations": []
  },
  {
    "statement": "One study on vessel speed limits was conducted in the North Atlantic Ocean in the USA.",
    "citations": []
  },
  {
    "statement": "The Indian River study found that the number of manatee deaths was similar before and after vessel speed limits were set in 'zones'.",
    "citations": []
  },
  {
    "statement": "The Indian River study found there were fewer manatee deaths after speed limits were set and enforced in all areas.",
    "citations": []
  },
  {
    "statement": "The North Atlantic study found that setting vessel speed limits during specific periods in key habitats resulted in fewer deaths of North Atlantic right whales caused by collisions.",
    "citations": []
  },
  {
    "statement": "All other intervention types for reducing lethal vessel collisions with marine mammals have no evidence base.",
    "citations": []
  },
  {
    "statement": "No studies were found for the intervention of using observers on board vessels.",
