    "statement": "No studies were found for the intervention of providing vessel operator training.",
    "citations": []
  },
  {
    "statement": "No studies were found for the intervention of modifying vessels.",
    "citations": []
  },
  {
    "statement": "No studies were found for the intervention of using remote detection tools.",
    "citations": []
  },
  {
    "statement": "No studies were found for the intervention of using real-time automated detection tools.",
    "citations": []
  },
  {
    "statement": "No studies were found for the intervention of using technology and reporting systems.",
    "citations": []
  }
]

[
  {
    "statement": "Based on studies from the Pacific and Tasman Sea regions, translocation outcomes for marine mammals vary significantly depending on conservation goals.",
    "citations": []
  },
  {
    "statement": "In the North Pacific Ocean, studies on Hawaiian monk seal translocations for population re-establishment showed positive outcomes.",
    "citations": []
  },
  {
    "statement": "Translocated Hawaiian monk seal pups had 50-83% survival rates.",
    "citations": []
  },
  {
    "statement": "The survival rates for translocated Hawaiian monk seal pups were similar to or greater than non-translocated pups.",
    "citations": []
  },
  {
    "statement": "More than a quarter of translocated Hawaiian monk seals reproduced.",
    "citations": []
  },
  {
    "statement": "Translocated Hawaiian monk seals exhibited similar dispersal behavior to native-born pups.",
    "citations": []
  },
  {
    "statement": "Studies in the Tasman Sea focused on conflict reduction showed poor outcomes.",
    "citations": []
  },
  {
    "statement": "When Australian and New Zealand fur seals were translocated away from salmon farms, more than half or nearly all of the seals returned to the original sites.",
    "citations": []
  },
  {
    "statement": "Translocating Australian and New Zealand fur seals away from salmon farms was an ineffective approach for reducing human-wildlife conflict.",
    "citations": []
  }
]

[
  {
    "statement": "Evidence from 27 studies on marine mammal rehabilitation and release shows variable long-term survival outcomes.",
    "citations": []
  },
  {
    "statement": "Twenty-one studies with post-release monitoring found that 10-100% of dolphins, porpoises, whales, seals, sea lions and manatees survived after being released following rehabilitation.",
    "citations": []
  },
  {
    "statement": "The monitoring periods for the twenty-one studies on rehabilitated marine mammals ranged from three days to five years.",
    "citations": []
  },
  {
    "statement": "One controlled study found that at least 25% of California sea lions treated for toxic algae poisoning and released back into the wild died or had to be euthanized.",
    "citations": []
  },
  {
    "statement": "A study demonstrated that more than 25% of rehabilitated and released Hawaiian monk seals reproduced.",
    "citations": []
  },
  {
    "statement": "Eleven studies on the rescue and release of stranded or trapped marine mammals found survival rates of 17-100%.",
    "citations": []
  },
  {
    "statement": "The post-release monitoring periods in the eleven studies on stranded or trapped marine mammals ranged from three weeks to three years.",
    "citations": []
  },
  {
    "statement": "Studies on rescued and released marine mammals found that rescued and released common bottlenose dolphins were observed with calves one year later.",
    "citations": []
  },
  {
    "statement": "Hawaiian monk seal rescue and release, along with other interventions, resulted in more than 25% of the seals surviving and reproducing.",
    "citations": []
  },
  {
    "statement": "Two controlled studies showed that rehabilitated and released harbour porpoises and harbour seals had similar movements and behaviours to wild mammals.",
    "citations": []
  },
  {
    "statement": "One study found that California sea lions treated for toxic algae poisoning showed altered behavior compared to wild sea lions.",
    "citations": []
  }
]

